   "pageTitle": "MCP Server",
   "heading": "What is MCP?",
   "headingLevel": 2,
   "site": "developer.sportradar.com",
   "href": "https://developer.sportradar.com/getting-started/docs/mcp-server#what-is-mcp",
   "anchored": true,
   "meta": false,
   "shared": false,
   "updatedAt": "2026-08-24",
   "asked": 0,
   "links": [],
