   "tags": [],
   "answer": "SIR(\"addWidget\", \"#sr-widget\", \"match.playerPropZone\", { matchId: \"67681902\", includedTabs: [\"goalscorers\", \"cards\"], tabOrder: [\"cards\", \"goalscorers\"], labelOverrides: { goalscorers: { label: \"Goals\", secondaryTabLabels: { 40: \"Any\", }, }, }, onAction: function (data) { console.log(data); }, }); <div id=\"sr-widget\"></div>",
