   "aliases": [],
   "tags": [],
   "answer": "onAction: function (action) { const { type, data } = action; switch (type) { case \"Close\": { if (data.source === \"CloseSolution\") { // Hide or destroy the widget container (header close). } break; } case \"Error\": { // Surface data.error / data.details to the user or your logger. break; } case \"AddSelectionsToBetSlip\": { // Add data.selections to the bet slip. break; } case \"CustomBetAddToBetSlip\": { // Map data.selectedOutcomes to your bet slip (requires enableCustomBet). break; } default: // Optional: ignore or log unexpected types for forward compatibility. break; } },",
