   "site": "apidocs.sportradar.com",
   "href": "https://apidocs.sportradar.com/resources/widgets/docs/tutorials/examples/adapter-flash-bet-endpoint-example#option-b-implement-eventmarkets",
   "anchored": true,
   "meta": false,
   "shared": true,
   "updatedAt": "",
